package com.paytrace.explanation; import com.paytrace.decision.*; import com.paytrace.incident.*; import com.paytrace.payment.*; import com.paytrace.recovery.*; import org.springframework.stereotype.Component; import java.util.*;
@Component public class OfflineExplanationModel implements ExplanationModelPort { public Optional<IncidentExplanation> explain(PaymentView p,List<Incident> i,DecisionAssessment d,RecoveryRecommendation r){return Optional.of(new IncidentExplanation("Deterministic investigation for payment "+p.paymentId()+" found "+i.getFirst().incidentType()+".","The summary is derived only from persisted payment, provider, webhook, and ledger evidence.",d.financialImpactLikely()?"Capture evidence may represent financial impact.":"No capture evidence indicates financial impact.",r.rationale(),List.of("Follow the authoritative recovery action: "+r.action()),"offline-evidence-summary"));} }
